/** Parser + verifier for prooflab JSON files, so proofs generated by the
 * CLI verify in the browser (and vice versa). See docs/format-spec.md. */

import { verifyReveal } from "./commitments";
import { verifyProof, type ProofStep } from "./merkle";
import * as schnorr from "./schnorr";
import * as signatures from "./signatures";

export const FORMAT_VERSION = 1;

export interface ProoflabDoc {
  format: "prooflab";
  version: number;
  type: string;
  [key: string]: unknown;
}

export function parseDoc(jsonText: string): ProoflabDoc {
  let doc: unknown;
  try {
    doc = JSON.parse(jsonText);
  } catch {
    throw new Error("not valid JSON");
  }
  if (typeof doc !== "object" || doc === null) {
    throw new Error("not a JSON object");
  }
  const d = doc as Record<string, unknown>;
  if (d.format !== "prooflab") {
    throw new Error('not a prooflab file (missing "format": "prooflab")');
  }
  if (d.version !== FORMAT_VERSION) {
    throw new Error(`unsupported format version: ${String(d.version)}`);
  }
  if (typeof d.type !== "string") {
    throw new Error("missing type field");
  }
  return d as ProoflabDoc;
}

function str(doc: ProoflabDoc, field: string): string {
  const value = doc[field];
  if (typeof value !== "string") {
    throw new Error(`missing or invalid field: ${field}`);
  }
  return value;
}

export interface VerifyOutcome {
  verdict: "valid" | "invalid" | "info";
  title: string;
  details: string[];
}

/**
 * Verify any self-contained prooflab document; for types that need extra
 * inputs (a message file, a second document), report what to supply.
 * `companions` may hold additional dropped documents (e.g. a commitment
 * alongside its reveal) and `messageBytes` the file a signature covers.
 */
export async function verifyDoc(
  doc: ProoflabDoc,
  companions: ProoflabDoc[] = [],
  messageBytes?: Uint8Array,
): Promise<VerifyOutcome> {
  switch (doc.type) {
    case "merkle_proof": {
      const path = doc.path as ProofStep[];
      if (!Array.isArray(path)) throw new Error("missing proof path");
      const item = str(doc, "item");
      const root = str(doc, "root");
      const ok = await verifyProof(item, path, root);
      return {
        verdict: ok ? "valid" : "invalid",
        title: ok ? "Merkle proof valid" : "Merkle proof INVALID",
        details: ok
          ? [
              `"${item}" is in the set committed to by root ${root.slice(0, 16)}…`,
              `Proof size: ${path.length} hashes — the whole set was never disclosed.`,
              "Check the root against the copy you trust: a proof is only as good as its root.",
            ]
          : ["The item is not in the set, or the proof or root was altered."],
      };
    }

    case "schnorr_proof": {
      const group = schnorr.GROUPS[str(doc, "group")];
      if (!group) throw new Error(`unknown group: ${String(doc.group)}`);
      const proof: schnorr.Proof = {
        group,
        y: BigInt("0x" + str(doc, "public_key")),
        R: BigInt("0x" + str(doc, "commitment")),
        s: BigInt("0x" + str(doc, "response")),
        message: str(doc, "message"),
      };
      const ok = await schnorr.verify(proof);
      return {
        verdict: ok ? "valid" : "invalid",
        title: ok ? "Schnorr proof valid" : "Schnorr proof INVALID",
        details: ok
          ? [
              "The prover knows the private key behind this public key — the key itself was never revealed.",
              proof.message
                ? `Bound to message: "${proof.message}"`
                : "Not bound to any message.",
            ]
          : ["The proof does not verify: wrong key, altered message, or tampered values."],
      };
    }

    case "commitment": {
      const reveal = companions.find((c) => c.type === "commitment_reveal");
      if (!reveal) {
        return {
          verdict: "info",
          title: "Commitment recorded",
          details: [
            `Commitment: ${str(doc, "commitment").slice(0, 32)}…`,
            "Drop the matching reveal file to check it.",
          ],
        };
      }
      const ok = await verifyReveal(
        str(doc, "commitment"),
        str(reveal, "secret"),
        str(reveal, "salt"),
      );
      return {
        verdict: ok ? "valid" : "invalid",
        title: ok ? "Reveal matches commitment" : "Reveal does NOT match",
        details: ok
          ? [`The committer locked in "${str(reveal, "secret")}" and did not change it.`]
          : ["Wrong secret, wrong salt, or the committer is cheating."],
      };
    }

    case "commitment_reveal": {
      const commitment = companions.find((c) => c.type === "commitment");
      if (!commitment) {
        return {
          verdict: "info",
          title: "Reveal file loaded",
          details: [
            `Secret: "${str(doc, "secret")}"`,
            "Drop the matching commitment file to check it.",
          ],
        };
      }
      return verifyDoc(commitment, [doc]);
    }

    case "signature": {
      if (!messageBytes) {
        return {
          verdict: "info",
          title: "Signature file loaded",
          details: [
            `Signed file: ${String(doc.file_name ?? "unknown")}`,
            "Add the original file so the signature can be checked against it.",
          ],
        };
      }
      const ok = await signatures.verify(
        str(doc, "public_key"),
        messageBytes,
        str(doc, "signature"),
      );
      return {
        verdict: ok ? "valid" : "invalid",
        title: ok ? "Signature valid" : "Signature INVALID",
        details: ok
          ? ["The file is unmodified and was signed by the holder of this key."]
          : ["The file changed, or it was not signed by this public key."],
      };
    }

    case "file_hash": {
      return {
        verdict: "info",
        title: "File hash record",
        details: [
          `File: ${String(doc.file_name ?? "unknown")}`,
          `SHA-256: ${str(doc, "digest")}`,
          "Re-hash your copy in the Hash lab and compare digests.",
        ],
      };
    }

    default:
      throw new Error(`unknown document type: ${doc.type}`);
  }
}
